def preencher(apps, schema_editor):
    Empresa = apps.get_model("plataforma", "Empresa")
    Fatura = apps.get_model("plataforma", "FaturaAssinatura")
    Forma = apps.get_model("plataforma", "FormaPagamentoAssinatura")
    Sequencia = apps.get_model("comum", "Sequencia")
    for empresa in Empresa.objects.exclude(schema_name="public"):
        if not empresa.email_cobranca:
            empresa.email_cobranca = empresa.responsavel_email
        if empresa.teste_fim and not empresa.dia_vencimento:
            empresa.dia_vencimento = (empresa.teste_fim + timedelta(days=1)).day
        empresa.save(update_fields=["email_cobranca", "dia_vencimento"])
        Forma.objects.get_or_create(empresa=empresa)
        if (
            not empresa.plano_id
            or not empresa.dia_vencimento
            or Fatura.objects.filter(empresa=empresa).exists()
        ):
            continue
        vencimento = empresa.teste_fim + timedelta(days=1)
        periodo = proximo_periodo(empresa.dia_vencimento, empresa.ciclo, vencimento)
        Fatura.objects.create(
            empresa=empresa,
            numero=1,
            codigo="FAT-0001",
            tipo="mensalidade",
            competencia=periodo.competencia,
            periodo_inicio=periodo.inicio,
            periodo_fim=periodo.fim,
            plano_id=empresa.plano_id,
            ciclo=empresa.ciclo,
            valor_centavos=empresa.preco_contratado_centavos,
            vencimento=vencimento,
        )
        Sequencia.objects.update_or_create(chave=f"FAT-{empresa.pk}", defaults={"ultimo_numero": 1})


